import React, { useState } from 'react';
import { FaBox, FaTags, FaComments, FaEnvelope, FaStar, FaHome, FaUser, FaChevronDown } from 'react-icons/fa';
import '../../CSS/Sidebar.css';

const Sidebar = () => {
  const [isProductOpen, setIsProductOpen] = useState(false);

  return (
    <div className="sidebar">
      <h2 className="sidebar-title">Admin Panel</h2>
      <ul className="sidebar-list">
        <li className="active"><FaHome /> Orders</li>

        <li 
          onMouseEnter={() => setIsProductOpen(true)}
          onMouseLeave={() => setIsProductOpen(false)}
          className="dropdown-parent"
        >
          <div className="dropdown-toggle">
            <FaBox />
            <span>Products</span>
            <FaChevronDown className={`chevron-icon ${isProductOpen ? 'rotate' : ''}`} />
          </div>
          {isProductOpen && (
            <ul className="dropdown-menu">
              <li><Link to="/manage-collection">Manage Collection</Link></li>
              <li><Link to="/add-bulk-products">Add Bulk Products</Link></li>
              <li><Link to="/manage-products">Manage Products</Link></li>
            </ul>
          )}
        </li>

        <li><FaTags /> Vouchers</li>
        <li><FaComments /> Live Chat</li>
        <li><FaEnvelope /> B2B Inquiries</li>
        <li><FaStar /> Reviews</li>
      </ul>
      <div className="sidebar-footer">
        <FaUser /> Admin
      </div>
    </div>
  );
};

export default Sidebar;
